/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for p in sorted(Path('reports').glob('*.md')):
 print('\\n'+str(p))
 for i,line in enumerate(p.read_text().splitlines(),1):
  qs=re.findall('“(["'^”]+)”'"',line)
  for q in qs:
   matches=[]
   for s in sorted(Path('archive').rglob('*')):
    if s.is_file() and q in s.read_text(): matches.append(str(s))
   print(i,repr(q),'MATCH',matches)
 print('LINK PATHS', re.findall(r'\\]\\(<?(["'^)>]+)>?'"\\)',p.read_text()))
files=[p for p in Path('archive').rglob('*') if p.is_file()]
print('\\nArchive files',len(files),'bytes',sum(p.stat().st_size for p in files))
PY"

